import{_ as a,o as n,c as e,ai as i}from"./chunks/framework.Ba-VnP44.js";const o=JSON.parse('{"title":"分析与决策提示词（10 条）","description":"","frontmatter":{},"headers":[],"relativePath":"ai/prompts/analysis.md","filePath":"ai/prompts/analysis.md"}'),l={name:"ai/prompts/analysis.md"};function p(r,s,t,c,b,d){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="分析与决策提示词-10-条" tabindex="-1">分析与决策提示词（10 条） <a class="header-anchor" href="#分析与决策提示词-10-条" aria-label="Permalink to “分析与决策提示词（10 条）”">​</a></h1><blockquote><p>做对比、定方案、看数据时用的 10 条。维度必须由我给，权重必须由我给。 通用骨架：背景 → 现状 → 目标 → 约束 → 输出格式，见 <a href="/my-vitepress-site/ai/prompts/">提示词库总览</a>。</p></blockquote><h2 id="模板" tabindex="-1">模板 <a class="header-anchor" href="#模板" aria-label="Permalink to “模板”">​</a></h2><h3 id="_1-需求真伪拆解" tabindex="-1">1. 需求真伪拆解 <a class="header-anchor" href="#_1-需求真伪拆解" aria-label="Permalink to “1. 需求真伪拆解”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>背景：需求方提出【原始需求原话】，他的角色是【…】，业务场景是【…】。</span></span>
<span class="line"><span>任务：先别给方案，帮我判断这是不是真需求：</span></span>
<span class="line"><span>1) 他说的“问题”和“他想要的解法”分别是什么，两者是否对应；</span></span>
<span class="line"><span>2) 不做会怎样？谁受影响、影响多大、多久一次；</span></span>
<span class="line"><span>3) 有没有更便宜的办法达到同样效果；</span></span>
<span class="line"><span>4) 如果一定要做，最小可交付是什么。</span></span>
<span class="line"><span>输出：结论 + 三条追问（我要拿去问需求方），不要给技术方案。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="_2-方案对比-决策矩阵" tabindex="-1">2. 方案对比（决策矩阵） <a class="header-anchor" href="#_2-方案对比-决策矩阵" aria-label="Permalink to “2. 方案对比（决策矩阵）”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>背景：要在【A/B/C】之间选，场景是【…】，我的约束是【工期、人力、预算、技术栈】。</span></span>
<span class="line"><span>任务：用决策矩阵对比。</span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1) 维度由你提，但每个维度要说清“为什么它对这个决策重要”；</span></span>
<span class="line"><span>2) 给每个维度定权重（合计 100），并说明权重依据我的约束怎么来的；</span></span>
<span class="line"><span>3) 打分时只用事实，缺数据就标【无数据】，不要猜；</span></span>
<span class="line"><span>4) 最后给推荐，并写明“如果权重变成 X，结论会翻转成哪个”。</span></span>
<span class="line"><span>输出：表格 + 一段不超过 200 字的结论。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_3-调研-竞品-工具-方案" tabindex="-1">3. 调研（竞品 / 工具 / 方案） <a class="header-anchor" href="#_3-调研-竞品-工具-方案" aria-label="Permalink to “3. 调研（竞品 / 工具 / 方案）”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>背景：我要调研【领域/产品】，目的是【选型 / 定价参考 / 做差异化】。</span></span>
<span class="line"><span>任务：给一份调研框架 + 首轮初稿。</span></span>
<span class="line"><span>要求：维度固定为——它解决什么问题、目标用户、核心能力、明显短板、定价模式、可替代性；每条结论后面标信源（官方文档 / 用户评价 / 我的推测），推测必须显式标注；</span></span>
<span class="line"><span>不确定的直接写“未查到”，不要用行业常识填空。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_4-数据解读" tabindex="-1">4. 数据解读 <a class="header-anchor" href="#_4-数据解读" aria-label="Permalink to “4. 数据解读”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>背景：这些是【业务指标】在【时间段】的数据：【贴数据或表格】。</span></span>
<span class="line"><span>任务是：不要罗列数字，回答三个问题——发生了什么变化、最可能的两个原因分别是什么、还需要什么数据才能确认。</span></span>
<span class="line"><span>要求：区分“相关”和“因果”；指出数据本身的局限（口径、样本量、季节性）；不要给“建议加强运营”这种无法执行的结论。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_5-上线风险评估" tabindex="-1">5. 上线风险评估 <a class="header-anchor" href="#_5-上线风险评估" aria-label="Permalink to “5. 上线风险评估”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>背景：要上线【功能】，涉及【表结构变更 / 接口变更 / 第三方依赖】，影响【用户量/调用方】。</span></span>
<span class="line"><span>任务：给风险清单，按“发生概率 × 影响面”排序，每条包含：触发条件、表现、检测方式、止损动作（具体到命令或开关）、责任人。</span></span>
<span class="line"><span>要求：至少覆盖数据兼容、灰度、回滚、依赖超时、并发峰值、监控盲区六项；没有兜底手段的项要明确写“无兜底，风险自担”。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_6-业务-项目复盘" tabindex="-1">6. 业务 / 项目复盘 <a class="header-anchor" href="#_6-业务-项目复盘" aria-label="Permalink to “6. 业务 / 项目复盘”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>背景：项目【名称】，目标【原定指标】，实际【结果】，周期【…】。</span></span>
<span class="line"><span>任务：写复盘，结构——目标与结果对照 / 关键动作与效果（哪些有效、哪些无效）/ 失真原因（判断、执行、外部）/ 可复用结论 / 下次怎么做。</span></span>
<span class="line"><span>要求：只写有证据的结论；区分“运气”和“能力”；每条结论要能被下一个项目直接执行。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_7-成本收益测算" tabindex="-1">7. 成本收益测算 <a class="header-anchor" href="#_7-成本收益测算" aria-label="Permalink to “7. 成本收益测算”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>背景：要做的事是【…】，投入【人力/时间/钱】，预期收益【…】。</span></span>
<span class="line"><span>任务：给一个粗算模型：一次性成本、持续成本、收益口径、回本周期，并做三档估算（乐观/中性/悲观）。</span></span>
<span class="line"><span>要求：每个数字标来源（报价 / 历史数据 / 假设）；假设单独列一节；最后给“什么条件下这件事不值得做”。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_8-反方视角-red-team" tabindex="-1">8. 反方视角（red team） <a class="header-anchor" href="#_8-反方视角-red-team" aria-label="Permalink to “8. 反方视角（red team）”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>背景：我倾向的方案是【…】，理由是【…】。</span></span>
<span class="line"><span>任务：站在反方，尽可能有力地证明我错了：</span></span>
<span class="line"><span>1) 我的论证里哪些是假设而非事实；</span></span>
<span class="line"><span>2) 这个方案最可能怎么失败（按时间顺序描述失败路径）；</span></span>
<span class="line"><span>3) 如果一个比我资深的人反对，他最可能说什么；</span></span>
<span class="line"><span>4) 什么证据能让我改变主意。</span></span>
<span class="line"><span>要求：不要客套，不要“但也可能对”，要给可被检验的反驳。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="_9-优先级排序" tabindex="-1">9. 优先级排序 <a class="header-anchor" href="#_9-优先级排序" aria-label="Permalink to “9. 优先级排序”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>背景：待办清单如下【列表】，我的资源是【人/时间】。</span></span>
<span class="line"><span>任务：按“价值 ÷ 成本”排序，价值用【影响用户数 × 严重程度】，成本用【人日】估。</span></span>
<span class="line"><span>要求：先给排序结果，再给每项的估值依据；指出哪些是“做了也看不出来”的低感知项；给出“如果只能做三件，做哪三件”。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_10-决策记录-adr-风格" tabindex="-1">10. 决策记录（ADR 风格） <a class="header-anchor" href="#_10-决策记录-adr-风格" aria-label="Permalink to “10. 决策记录（ADR 风格）”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>背景：我们已经决定【方案】，做了【…】的取舍。</span></span>
<span class="line"><span>任务：写成一份决策记录：背景 / 备选方案 / 决定 / 理由 / 已知代价 / 复核条件（什么情况下重新评估）。</span></span>
<span class="line"><span>要求：写清“当时不知道什么”，方便半年后的人理解这不是拍脑袋；不要美化决策过程。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><p>同类：<a href="/my-vitepress-site/ai/prompts/coding.html">编程开发</a> · <a href="/my-vitepress-site/ai/prompts/writing.html">写作与表达</a> · <a href="/my-vitepress-site/ai/prompts/learning.html">学习与理解</a> · <a href="/my-vitepress-site/ai/prompts/creation.html">创意与内容</a> · <a href="/my-vitepress-site/ai/prompts/agent.html">角色与系统提示词</a></p>`,25)])])}const u=a(l,[["render",p]]);export{o as __pageData,u as default};
